import pathlib,json,hashlib,datetime,subprocess,psutil,ctypes,os,csv
k=ctypes.WinDLL('kernel32',use_last_error=True)
k.GetCurrentProcess.restype=ctypes.c_void_p
k.SetProcessAffinityMask.argtypes=[ctypes.c_void_p,ctypes.c_size_t]
assert k.SetProcessAffinityMask(k.GetCurrentProcess(),1)
q=pathlib.Path('D:/PROJECTS/.cognition/gpu_queue')
def queue_info(p):
 b=p.read_bytes()
 d=json.loads(b)
 out={'file':str(p),'sha256':hashlib.sha256(b).hexdigest(),'name':d.get('name'),'pid':d.get('pid'),'child_pid':d.get('child_pid')}
 for key,clock in [('pid','ctime'),('child_pid','child_ctime')]:
  pid=d.get(key); ctime=d.get(clock)
  if type(pid) is not int or type(ctime) not in (int,float):
   out[key+'_identity']='UNKNOWN'
  else:
   try: out[key+'_identity']='MATCH' if abs(psutil.Process(pid).create_time()-ctime)<2 else 'MISMATCH'
   except (psutil.NoSuchProcess,psutil.AccessDenied): out[key+'_identity']='UNKNOWN_OR_NOT_RUNNING'
 return out
started=datetime.datetime.now(datetime.timezone.utc).isoformat()
holder=queue_info(q/'holder.json') if (q/'holder.json').is_file() else None
tickets=[queue_info(p) for p in sorted((q/'tickets').glob('*.json'))]
gpu=subprocess.run(['C:/Windows/System32/nvidia-smi.exe','--query-gpu=index,name,driver_version,memory.used,memory.total,temperature.gpu,utilization.gpu','--format=csv,noheader,nounits'],capture_output=True,text=True,timeout=5)
gpu_rows=[]
if gpu.returncode==0:
 for row in csv.reader(gpu.stdout.splitlines()):
  if len(row)==7:
   row=[v.strip() for v in row]
   gpu_rows.append(dict(zip(['index','name','driver_version','memory_used_MiB','memory_total_MiB','temperature_C','utilization_percent'],row)))
apps=subprocess.run(['C:/Windows/System32/nvidia-smi.exe','--query-compute-apps=pid,process_name,used_gpu_memory','--format=csv,noheader,nounits'],capture_output=True,text=True,timeout=5)
gpu_apps=[]
if apps.returncode==0:
 for row in csv.reader(apps.stdout.splitlines()):
  if len(row)==3: gpu_apps.append({'pid':row[0].strip(),'name':pathlib.Path(row[1].strip()).name,'used_gpu_memory_MiB':row[2].strip()})
processes=[]
scan_errors=0
for p in psutil.process_iter(['name','memory_info']):
 try:
  n=p.info['name'] or ''
  if n.lower().startswith(('python','blender','claude')):
   processes.append({'pid':p.pid,'name':n,'rss_bytes':p.info['memory_info'].rss})
 except (psutil.AccessDenied,psutil.NoSuchProcess): scan_errors+=1
roots=[
 pathlib.Path('C:/Program Files/NVIDIA GPU Computing Toolkit/CUDA'),
 pathlib.Path('C:/ProgramData/NVIDIA Corporation'),
 pathlib.Path('C:/Program Files/NVIDIA Corporation'),
 pathlib.Path('C:/VulkanSDK')]
sdk=[]
root_status=[]
for p in roots:
 try:
  exists=p.is_dir()
  root_status.append({'path':str(p),'exists':exists})
  if exists:
   for entry in p.iterdir():
    if entry.is_dir() and ('optix' in entry.name.lower() or p.name in ('CUDA','VulkanSDK')):
     sdk.append({'directory':str(entry),'optix_header':(entry/'include/optix.h').is_file(),'optix_device_header':(entry/'include/optix_device.h').is_file(),'cuda_header':(entry/'include/cuda.h').is_file(),'vulkan_header':(entry/'Include/vulkan/vulkan.h').is_file()})
 except PermissionError: root_status.append({'path':str(p),'access':'UNREADABLE'})
envpaths={n:os.environ.get(n) for n in ['CUDA_PATH','CUDAToolkit_ROOT','OPTIX_ROOT','OPTIX_ROOT_DIR','VULKAN_SDK'] if os.environ.get(n)}
ram=psutil.virtual_memory().available
out={'id':'MEGA-GEOMETRY-HOST-READINESS-READONLY-001','started_utc':started,'finished_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'queue_directory_exists':q.is_dir(),'queue_holder':holder,'queue_tickets':tickets,'queue_mutated':False,'ram_available_bytes':ram,'ram_margin_above_4GiB_before_budget_bytes':ram-4*2**30,'gpu_query_exit_code':gpu.returncode,'gpu_devices':gpu_rows,'gpu_apps_query_exit_code':apps.returncode,'gpu_apps':gpu_apps,'host_processes_in_scope':processes,'host_process_scan_errors':scan_errors,'sdk_roots_in_scope':root_status,'sdk_directories_in_scope':sdk,'sdk_environment_paths_in_scope':envpaths,'GPU_workload_launched':False,'native_cluster_capability_queried':False,'native_cluster_capability':'UNKNOWN','SDK_installed':False,'GPU_admission':False,'scope':'CPU read-only telemetry and named SDK locations only, not SDK global inventory or reservation','JEV':'LOCAL_SECURITY_BLOCKED_NO_RETRY_NO_REMOTE_ENDORSEMENT'}
print(json.dumps(out,ensure_ascii=True))
